        remaining = re.sub(r"HAL_GPIO_EXTI_IRQHandler\s*\(\s*\w+\s*\)\s*;", "", handler_body)
        called_pins = [pins_get(pin)[0] for pin in calls]
        if (remaining.strip() or not 1 <= len(calls) <= 16 or
