uint8_t PlatformGpio_IrqConsume(PlatformGpioId id)
{
    uint8_t pending;
    PlatformCriticalState saved;
    if ((id != PLATFORM_GPIO_3) || (s_initialized == 0U)) { return 0U; }
    saved = PlatformCritical_Enter();
    pending = s_dio1_pending;
    s_dio1_pending = 0U;
